from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump = {a: b for a, b in jumps}

    def resolve(x: int) -> int:
        # Follow jump chains; the problem guarantees they terminate.
        while x in jump:
            x = jump[x]
        return x

    def step(p: int, r: int) -> int:
        q = p + r
        if q > n:
            q = 2 * n - q  # bounce back from the far end
        return resolve(q)

    # Collect resting cells reachable from the start (cell n is terminal).
    seen = {0}
    stack = [0]
    edges = {}
    while stack:
        x = stack.pop()
        nxt = [step(x, r) for r in range(1, m + 1)]
        edges[x] = nxt
        for y in nxt:
            if y != n and y not in seen:
                seen.add(y)
                stack.append(y)

    # If some reachable cell cannot reach n, the game may never end.
    good = set()
    changed = True
    while changed:
        changed = False
        for x in seen:
            if x not in good and any(y == n or y in good for y in edges[x]):
                good.add(x)
                changed = True
    if len(good) < len(seen):
        return None

    # Solve E[x] = 1 + (1/m) * sum E[y] over reachable resting cells, with E[n] = 0.
    order = sorted(seen)
    idx = {x: i for i, x in enumerate(order)}
    k = len(order)
    M = [[Fraction(0)] * (k + 1) for _ in range(k)]
    for x in order:
        i = idx[x]
        M[i][i] += 1
        M[i][k] = Fraction(1)
        for y in edges[x]:
            if y != n:
                M[i][idx[y]] -= Fraction(1, m)

    # Gauss-Jordan elimination with exact fractions.
    for col in range(k):
        piv = next(r for r in range(col, k) if M[r][col] != 0)
        M[col], M[piv] = M[piv], M[col]
        inv = 1 / M[col][col]
        M[col] = [v * inv for v in M[col]]
        for r in range(k):
            if r != col and M[r][col] != 0:
                f = M[r][col]
                M[r] = [a - f * b for a, b in zip(M[r], M[col])]

    ans = M[idx[0]][k]
    return [ans.numerator, ans.denominator]
